// ─── PLAYER ─────────────────────────────────────────────────────────────────
const playlist = [
  {title:'Dynamite', artist:'BTS'},{title:'Butter', artist:'BTS'},{title:'Permission to Dance', artist:'BTS'},
  {title:'Spring Day', artist:'BTS'},{title:'Blood Sweat & Tears', artist:'BTS'},{title:'Boy With Luv', artist:'BTS'},
  {title:'Life Goes On', artist:'BTS'},{title:'Yet To Come', artist:'BTS'},{title:'DNA', artist:'BTS'},
];
let currentTrack=0, playing=false, progress=0, playerInterval=null;

function showPlayer(){document.getElementById('mini-player').classList.remove('hidden');document.getElementById('player-toggle').classList.remove('visible');loadTrack(currentTrack);}
function hidePlayer(){document.getElementById('mini-player').classList.add('hidden');document.getElementById('player-toggle').classList.add('visible');if(playerInterval)clearInterval(playerInterval);playing=false;}
function loadTrack(i){const t=playlist[i];document.getElementById('player-track').textContent=t.title;document.getElementById('player-artist').textContent=t.artist;progress=0;document.getElementById('player-bar').style.width='0%';}
function togglePlay(){playing=!playing;document.getElementById('play-btn').textContent=playing?'⏸':'▶';if(playing){playerInterval=setInterval(()=>{progress+=0.5;if(progress>=100){nextTrack();return;}document.getElementById('player-bar').style.width=progress+'%';},150);}else{clearInterval(playerInterval);}}
function nextTrack(){clearInterval(playerInterval);progress=0;currentTrack=(currentTrack+1)%playlist.length;loadTrack(currentTrack);if(playing)togglePlay();}
function prevTrack(){clearInterval(playerInterval);progress=0;currentTrack=(currentTrack-1+playlist.length)%playlist.length;loadTrack(currentTrack);if(playing)togglePlay();}
function seekPlayer(e){const rect=e.currentTarget.getBoundingClientRect();progress=(e.clientX-rect.left)/rect.width*100;document.getElementById('player-bar').style.width=progress+'%';}

// ─── THEME ──────────────────────────────────────────────────────────────────
function initTheme(){const t=localStorage.getItem('bts-theme')||'light';document.documentElement.setAttribute('data-theme',t);document.getElementById('theme-btn').textContent=t==='dark'?'☀️ Modo':'🌙 Modo';}
document.getElementById('theme-btn').addEventListener('click',()=>{const cur=document.documentElement.getAttribute('data-theme');const next=cur==='dark'?'light':'dark';document.documentElement.setAttribute('data-theme',next);localStorage.setItem('bts-theme',next);document.getElementById('theme-btn').textContent=next==='dark'?'☀️ Modo':'🌙 Modo';});

// ─── SEARCH ─────────────────────────────────────────────────────────────────
document.getElementById('search-btn').addEventListener('click',()=>{document.getElementById('search-overlay').classList.add('open');setTimeout(()=>document.getElementById('search-input').focus(),100);});
function closeSearchBox(){document.getElementById('search-overlay').classList.remove('open');document.getElementById('search-input').value='';document.getElementById('search-results').innerHTML='<div class="search-empty">Escribí para buscar...</div>';}
function closeSearch(e){if(e.target===document.getElementById('search-overlay'))closeSearchBox();}
document.getElementById('search-input').addEventListener('input',function(){
  const q=this.value.toLowerCase().trim();
  if(!q){document.getElementById('search-results').innerHTML='<div class="search-empty">Escribí para buscar...</div>';return;}
  const results=[];
  Object.keys(membersData).forEach(m=>{if(m.toLowerCase().includes(q))results.push({tag:'Integrante',name:m,action:`closeSearchBox();openMemberModal('${m}')`});});
  Object.values(groupAlbums).forEach((a,i)=>{if(a.title.toLowerCase().includes(q))results.push({tag:'Álbum',name:a.title,action:`closeSearchBox();openAlbum('${Object.keys(groupAlbums)[i]}','group')`});});
  Object.values(soloAlbumsData).forEach((a,i)=>{if(a.title.toLowerCase().includes(q)||a.member.toLowerCase().includes(q))results.push({tag:'Solista',name:`${a.member} — ${a.title}`,action:`closeSearchBox();openAlbum('${Object.keys(soloAlbumsData)[i]}','solo')`});});
  allSongs.forEach(s=>{if(s.toLowerCase().includes(q))results.push({tag:'Canción',name:s,action:`closeSearchBox()`});});
  const html=results.length?results.slice(0,8).map(r=>`<div class="search-result-item" onclick="${r.action}"><span class="search-result-tag">${r.tag}</span><span class="search-result-name">${r.name}</span></div>`).join(''):'<div class="search-empty">Sin resultados para "'+q+'"</div>';
  document.getElementById('search-results').innerHTML=html;
});

