let favs=JSON.parse(localStorage.getItem('bts-favs')||'[]');
function toggleFav(name){if(favs.includes(name)){favs=favs.filter(f=>f!==name);}else{favs.push(name);}localStorage.setItem('bts-favs',JSON.stringify(favs));updateFavUI();}
function updateFavUI(){document.querySelectorAll('.fav-heart').forEach(btn=>{const name=btn.id.replace('fav-','');btn.textContent=favs.includes(name)?'♥':'♡';btn.classList.toggle('active',favs.includes(name));});}

